import csv
import io


def parse_csv(raw_csv: str):
    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False,
    )

    records = []
    for record in reader:
        if not record or all(value.strip() == "" for value in record):
            continue
        records.append(record)

    start = 0
    while start < len(records) and records[start][0].lstrip().startswith("#"):
        start += 1

    if start >= len(records):
        return {"columns": [], "rows": []}

    columns = list(records[start])
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    data_rows = records[start + 1:]
    width = max([len(columns)] + [len(row) for row in data_rows])

    while len(columns) < width:
        name = f"extra_{len(columns) - len(records[start]) + 1}"
        while name in columns:
            name += "_"
        columns.append(name)

    normalized_rows = [
        row[:width] + [""] * max(0, width - len(row))
        for row in data_rows
    ]

    return {"columns": columns, "rows": normalized_rows}
